class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, item_name, quantity):
        for _ in range(quantity):
            self.items.append(item_name)
        print(f"Added {quantity} {item_name}(s) to cart.")

    def remove_item(self, item_name, quantity):
        removed_count = 0
        for _ in range(quantity):
            try:
                self.items.remove(item_name)
                removed_count += 1
            except ValueError:
                break
        print(f"Removed {removed_count} {item_name}(s) from cart.")

    def display_cart(self):
        if not self.items:
            print("Cart is empty.")
        else:
            print("Items in cart:")
            for index, item in enumerate(self.items, start=1):
                print(f"{index}. {item}")

    def calculate_total(self):
        prices = {"apple": 1.5, "banana": 0.75, "orange": 1.25}
        total_cost = sum(prices[item] for item in set(self.items))
        print(f"Total cost of items in cart: ${total_cost:.2f}")

