import logging
from datetime import datetime

class CustomFormatter(logging.Formatter):
    def format(self, record):
        current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        record.message = f'{current_time} {record.levelname}: {record.getMessage()}'
        return super().format(record)

class FileHandlerWithTimestamp(logging.FileHandler):
    def __init__(self, filename, mode='a', encoding=None, delay=False):
        super().__init__(filename, mode, encoding, delay)
        self.setFormatter(CustomFormatter())

def create_logger(logfile):
    logger = logging.getLogger('my_logger')
    logger.setLevel(logging.INFO)
    handler = FileHandlerWithTimestamp(logfile)
    logger.addHandler(handler)
    return logger

def log_custom_message(logger, message):
    logger.info(message)

logger = create_logger('app.log')
log_custom_message(logger, "This is a custom log message.")

