class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, item, quantity):
        self.items.append((item, quantity))
        print(f"Added {quantity} of {item} to cart.")

    def remove_item(self, item, quantity):
        for i in range(len(self.items)):
            if self.items[i][0] == item:
                if self.items[i][1] >= quantity:
                    self.items[i] = (item, self.items[i][1] - quantity)
                    if self.items[i][1] == 0:
                        del self.items[i]
                    print(f"Removed {quantity} of {item} from cart.")
                    return
        print(f"{item} not found in cart.")

    def view_cart(self):
        if not self.items:
            print("Cart is empty.")
        else:
            print("Items in cart:")
            for item, quantity in self.items:
                print(f"- {quantity} of {item}")

