import os

def load_image_files(directory):
    image_files = []
    for filename in os.listdir(directory):
        if filename.endswith(('.png', '.jpg', '.jpeg', '.bmp', '.gif')):
            image_files.append(os.path.join(directory, filename))
    return image_files

def resize_images(image_paths, target_size):
    from PIL import Image
    resized_images = []
    for image_path in image_paths:
        img = Image.open(image_path)
        img_resized = img.resize(target_size, Image.ANTIALIAS)
        resized_images.append(img_resized)
    return resized_images

def save_resized_images(resized_images, output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)
    for idx, img in enumerate(resized_images):
        img.save(os.path.join(output_dir, f'resized_{idx}.jpg'))

if __name__ == "__main__":
    input_dir = 'path/to/input/images'
    output_dir = 'path/to/output/images'
    target_size = (800, 600)
    image_files = load_image_files(input_dir)
    resized_images = resize_images(image_files, target_size)
    save_resized_images(resized_images, output_dir)

