    merge_sort(data)
    print("Sorted array:", data)

    target = 23
    result = binary_search(data, target)
    if result != -1:
        print(f"Element {target} is present at index {result}")
    else:
        print(f"Element {target} is not present in array")

async def vector_store_search(query: str, n_results: int=5, collection_name: str=VECTOR_CONFIG.collection_name, include_distances: bool=True) -> dict[str, Any]:
    try:
        collection = get_or_create_collection(collection_name)
        if collection.count() == 0:
            return {'success': True, 'message': 'Collection is empty. Add documents first.', 'results': [], 'total_documents': 0}
        include_list = ['documents', 'metadatas']
        if include_distances:
            include_list.append('distances')
        search_results = collection.query(query_texts=[query], n_results=min(n_results, collection.count()), include=include_list)
        results = []
        for rank, (doc_id, document, metadata) in enumerate(zip(search_results['ids'][0], search_results['documents'][0], search_results['metadatas'][0], strict=False), 1):
            result = {'id': doc_id, 'document': document, 'metadata': metadata, 'rank': rank}
            if include_distances:
                distance = search_results['distances'][0][rank - 1]
                result['similarity_score'] = max(0, 1 - distance)
                result['distance'] = distance
            results.append(result)
        return {'success': True, 'query': query, 'results': results, 'total_documents': collection.count(), 'returned_count': len(results)}
    except Exception as e:
        return {'success': False, 'error': f'Search failed: {str(e)}'}

