class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, item_name, price):
        self.items.append({"item_name": item_name, "price": price})
        print(f"Added {item_name} to the cart. Current total: ${sum(item['price'] for item in self.items)}")

    def remove_item(self, item_name):
        self.items = [item for item in self.items if item["item_name"] != item_name]
        print(f"Removed {item_name} from the cart. Current total: ${sum(item['price'] for item in self.items)}")

    def calculate_total(self):
        return sum(item["price"] for item in self.items)

    def display_cart(self):
        print("Current items in the cart:")
        for item in self.items:
            print(f"- {item['item_name']} ($ {item['price']})")
        print(f"Total: ${self.calculate_total()}")

cart = ShoppingCart()
cart.add_item("Apple", 0.5)
cart.add_item("Banana", 0.3)
cart.display_cart()
cart.remove_item("Apple")
cart.display_cart()

import re

def extract_emails(text):
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
    emails = re.findall(email_pattern, text)
    return emails

def replace_emails_with_placeholder(text):
    placeholder = "[REDACTED_EMAIL]"
    return re.sub(email_pattern, placeholder, text)

def main():
    input_text = "Please contact us at support@example.com or sales@example.org for further assistance."
    extracted_emails = extract_emails(input_text)
    print("Extracted Emails:", extracted_emails)

    redacted_text = replace_emails_with_placeholder(input_text)
    print("Redacted Text:", redacted_text)

if __name__ == "__main__":
    main()

