import random

def generate_board(size):
    return [[' ' for _ in range(size)] for _ in range(size)]

def print_board(board):
    for row in board:
        print(' | '.join(row))
        print('-' * (4 * len(row) - 1))

def check_win(board, player):
    size = len(board)
    # Check rows and columns
    for i in range(size):
        if all([board[i][j] == player for j in range(size)]) or all([board[j][i] == player for j in range(size)]):
            return True
    # Check diagonals
    if all([board[i][i] == player for i in range(size)]) or all([board[i][size-i-1] == player for i in range(size)]):
        return True
    return False

def is_full(board):
    return all([' ' not in row for row in board])

def tic_tac_toe():
    board_size = 3
    board = generate_board(board_size)
    print_board(board)

    players = ['X', 'O']
    current_player = random.choice(players)

    while True:
        try:
            row, col = map(int, input(f"Player {current_player}, enter your move (row col): ").split())
            if board[row][col] == ' ':
                board[row][col] = current_player
            else:
                print("Cell already occupied. Try again.")
                continue
            print_board(board)
            if check_win(board, current_player):
                print(f"Player {current_player} wins!")
                break
            if is_full(board):
                print("It's a draw!")
                break
            current_player = 'O' if current_player == 'X' else 'X'
        except (ValueError, IndexError):
            print("

