class ProductFactory:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(ProductFactory, cls).__new__(cls)
            cls._instance.products = {}
        return cls._instance

    def create_product(self, product_type, product_id):
        if product_type not in self.products:
            self.products[product_type] = {}
        if product_id not in self.products[product_type]:
            self.products[product_type][product_id] = f"Product {product_type}-{product_id}"
        return self.products[product_type][product_id]

    def get_product(self, product_type, product_id):
        return self.products.get(product_type, {}).get(product_id, None)


class Observer:
    def update(self, message):
        pass


class Observable:
    def __init__(self):
        self.observers = []

    def add_observer(self, observer):
        self.observers.append(observer)

    def remove_observer(self, observer):
        self.observers.remove(observer)

    def notify_observers(self, message):
        for observer in self.observers:
            observer.update(message)


class Inventory(Observable):
    def __init__(self):
        super().__init__()
        self.products = {}

    def add_product(self, product_type, product_id):
        product_factory = ProductFactory()
        product = product_factory.create_product(product_type, product_id)
        self.products[(product_type, product_id)] = product
        self.notify_observers(f"Added {product}")

    def remove_product(self, product_type, product_id):
        if (product_type, product_id) in self.products:
            del self.products[(product_type, product_id)]
            self.notify_observers(f"Removed {product_id} from {product_type}")


