def find_closest_value(arr, target):
    sorted_arr = merge_sort(arr)
    index = binary_search(sorted_arr, target)

    if index != -1:
        return sorted_arr[index]

    closest_index = -1
    min_diff = float('inf')

    for i in range(len(sorted_arr)):
        diff = abs(sorted_arr[i] - target)
        if diff < min_diff:
            min_diff = diff
            closest_index = i

    return sorted_arr[closest_index]

