import pytz
from datetime import datetime

def convert_timezone(dt_str, input_tz, output_tz):
    input_tz = pytz.timezone(input_tz)
    output_tz = pytz.timezone(output_tz)

    dt = datetime.strptime(dt_str, "%Y-%m-%d %H:%M:%S")
    dt = input_tz.localize(dt)
    dt = dt.astimezone(output_tz)

    return dt.strftime("%Y-%m-%d %H:%M:%S")

def process_time_conversions(records):
    converted_records = []
    for record in records:
        dt_str = record.get('timestamp', '')
        if dt_str:
            try:
                converted_time = convert_timezone(
                    dt_str, 
                    record.get('input_timezone', 'UTC'), 
                    record.get('output_timezone', 'Asia/Tokyo')
                )
                record['converted_timestamp'] = converted_time
                converted_records.append(record)
            except Exception as e:
                print(f"Error converting {dt_str}: {e}")
    return converted_records

