import random

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        last_node = self.head
        while last_node.next:
            last_node = last_node.next
        last_node.next = new_node

    def get_random_node(self):
        current_node = self.head
        random_index = random.randint(0, self.length() - 1)
        count = 0
        while count < random_index:
            current_node = current_node.next
            count += 1
        return current_node.value

    def length(self):
        count = 0
        current_node = self.head
        while current_node:
            count += 1
            current_node = current_node.next
        return count

    def display(self):
        values = []
        current_node = self.head
        while current_node:
            values.append(current_node.value)
            current_node = current_node.next
        return values

linked_list = LinkedList()
for i in range(10):
    linked_list.append(i)

random_value = linked_list.get_random_node()
