        self.books = [
            {"title": "Python Programming", "author": "Mark Summerfield", "available": True},
            {"title": "Effective Python", "author": "Brett Slatkin", "available": True},
            {"title": "Fluent Python", "author": "Luciano Ramalho", "available": False}
        ]

    def search_book(self, title):
        for book in self.books:
            if book["title"].lower() == title.lower():
                return book
        return None

    def borrow_book(self, title):
        book = self.search_book(title)
        if book and book["available"]:
            book["available"] = False
            return f"Book '{title}' borrowed successfully."
        elif book:
            return f"Book '{title}' is not available."
        else:
            return f"No book titled '{title}' found."

    def return_book(self, title):
        book = self.search_book(title)
        if book:
            book["available"] = True
            return f"Book '{title}' returned successfully."
        else:
            return f"No book titled '{title}' found."

