import random

class NumberGuessingGame:
    def __init__(self):
        self.secret_number = random.randint(1, 100)
        self.attempts = 0

    def guess(self, number):
        self.attempts += 1
        if number < self.secret_number:
            return "Too low!"
        elif number > self.secret_number:
            return "Too high!"
        else:
            return f"Congratulations! You guessed the number in {self.attempts} attempts."

def play_game():
    game = NumberGuessingGame()
    print("Welcome to the Number Guessing Game!")
    while True:
        try:
            guess = int(input("Guess the number between 1 and 100: "))
            result = game.guess(guess)
            print(result)
            if "Congratulations" in result:
                break
        except ValueError:
            print("Please enter a valid number.")

if __name__ == "__main__":
    play_game()

def calculate_mortgage(home_price: int, down_payment: int=None, down_payment_percent: float=None, loan_term: int=30, interest_rate: float=6.5, annual_property_tax: int=None, annual_homeowners_insurance: int=None, monthly_hoa: int=0, include_pmi: bool=True) -> Dict:
    if down_payment is None and down_payment_percent is None:
        down_payment_percent = 20.0
    if down_payment is None:
        down_payment = int(home_price * (down_payment_percent / 100))
    else:
        down_payment_percent = down_payment / home_price * 100
    loan_amount = home_price - down_payment
    monthly_interest_rate = interest_rate / 100 / 12
    total_payments = loan_term * 12
    if monthly_interest_rate > 0:
        monthly_principal_interest = loan_amount * (monthly_interest_rate * (1 + monthly_interest_rate) ** total_payments) / ((1 + monthly_interest_rate) ** total_payments - 1)
    else:
        monthly_principal_interest = loan_amount / total_payments
    monthly_pmi = 0
    if include_pmi and down_payment_percent < 20:
        monthly_pmi = loan_amount * 0.007 / 12
    monthly_property_tax = 0
    if annual_property_tax is not None:
        monthly_property_tax = annual_property_tax / 12
    else:
        annual_property_tax = int(home_price * 0.011)
        monthly_property_tax = annual_property_tax / 12
    monthly_homeowners_insurance = 0
    if annual_homeowners_insurance is not None:
        monthly_homeowners_insurance = annual_homeowners_insurance / 12
    else:
        annual_homeowners_insurance = int(home_price * 0.0035)
        monthly_homeowners_insurance = annual_homeowners_insurance / 12
    monthly_payment = monthly_principal_interest + monthly_pmi + monthly_property_tax + monthly_homeowners_insurance + monthly_hoa
    total_cost = monthly_payment * total_payments + down_payment
    return {'success': True, 'mortgage_details': {'home_price': home_price, 'down_payment': down_payment, 'down_payment_percent': round(down_payment_percent, 2), 'loan_amount': loan_amount, 'loan_term_years': loan_term, 'interest_rate': interest_rate, 'monthly_payment': round(monthly_payment, 2), 'monthly_principal_interest': round(monthly_principal_interest, 2), 'monthly_property_tax': round(monthly_property_tax, 2), 'monthly_homeowners_insurance': round(monthly_homeowners_insurance, 2), 'monthly_hoa': monthly_hoa, 'monthly_pmi': round(monthly_pmi, 2), 'total_interest_paid': round(monthly_principal_interest * total_payments - loan_amount, 2), 'total_payments': round(monthly_payment * total_payments, 2), 'total_cost': round(total_cost, 2)}, 'metadata': {'timestamp': datetime.now().isoformat(), 'source': 'Zillow Mortgage Calculator'}}

