def binary_search(arr, target):
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

def merge_sort(arr):
    if len(arr) > 1:
        mid = len(arr) // 2
        left_half = arr[:mid]
        right_half = arr[mid:]

        merge_sort(left_half)
        merge_sort(right_half)

        i = j = k = 0

        while i < len(left_half) and j < len(right_half):
            if left_half[i] < right_half[j]:
                arr[k] = left_half[i]
                i += 1
            else:
                arr[k] = right_half[j]
                j += 1
            k += 1

        while i < len(left_half):
            arr[k] = left_half[i]
            i += 1
            k += 1

        while j < len(right_half):
            arr[k] = right_half[j]
            j += 1
            k += 1

    return arr

if __name__ == "__main__":
    nums = [38, 27, 43, 3, 9, 82, 10]
    sorted_nums = merge_sort(nums.copy())
    print("Sorted array:", sorted_nums)

    target = 3
    index = binary_search(sorted_nums, target)
    print(f"Index of {target} in sorted array:", index)

import re

def extract_domain_and_subdomain(url):
    pattern = r'^(?:https?://)?(?:www\.)?([^/.]+)(.*)'
    match = re.match(pattern, url)
    if match:
        domain = match.group(1)
        subdomain = match.group(2)
        return domain, subdomain
    else:
        return None, None

def parse_query_params(url):
    query_start = url.find('?')
    if query_start == -1:
        return {}
    query_string = url[query_start+1:]
    params = {}
    pairs = query_string.split('&')
    for pair in pairs:
        key, value = pair.split('=')
        params[key] = value
    return params

def format_url(domain, subdomain, path, params):
    param_string = '&'.join([f'{k}={v}' for k, v in params.items()])
    query_string = '?' + param_string if param_string else ''
    return f'https://{subdomain}.{domain}/{path}{query_string}'

def process_url(url):
    domain, subdomain = extract_domain_and_subdomain(url)
    path, params_str = url[len(f'https://{subdomain}.{domain}/'):].split('?', 1)
    params = parse_query_params(f'?{params_str}')
    formatted_url = format_url(domain, subdomain, path, params)
    return formatted_url

