async def delay(input: DelayInput) -> dict:
    try:
        if not isinstance(input.delay, (int, float)) or input.delay < 0:
            raise ValueError('Delay must be a positive number')
        start_time = time.time()
        await asyncio.sleep(input.delay)
        end_time = time.time()
        actual_delay = end_time - start_time
        return {'success': True, 'status': 'completed', 'requested_delay': input.delay, 'actual_delay': actual_delay, 'message': f'Waited for {actual_delay:.3f} seconds'}
    except ValueError as e:
        return {'success': False, 'status': 'error', 'error': str(e)}
    except Exception as e:
        logger.error(f'Error in delay tool: {str(e)}')
        return {'success': False, 'status': 'error', 'error': str(e)}

def search_slack(query: str, community: str=None, year: str=None, top_n: int=5):
    filtered_docs = docs
    filtered_meta = meta
    if community:
        filtered_docs, filtered_meta = zip(*[(doc, meta) for doc, meta in zip(docs, meta) if meta['community'] == community])
    if year:
        filtered_docs, filtered_meta = zip(*[(doc, meta) for doc, meta in zip(filtered_docs, filtered_meta) if meta['year'] == year])
    matrix = tfidf_matrix if not (community or year) else vectorizer.transform(filtered_docs)
    query_vec = vectorizer.transform([query])
    similarities = cosine_similarity(query_vec, matrix).flatten()
    top_indices = similarities.argsort()[-top_n:][::-1]
    results = []
    for idx in top_indices:
        result = {'score': round(similarities[idx], 4), 'content': filtered_docs[idx], 'metadata': filtered_meta[idx]}
        results.append(result)
    return results

