import random

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_into_tree(root, value):
    if root is None:
        return TreeNode(value)
    else:
        if value < root.value:
            root.left = insert_into_tree(root.left, value)
        else:
            root.right = insert_into_tree(root.right, value)
    return root

def in_order_traversal(root):
    if root:
        in_order_traversal(root.left)
        print(root.value, end=' ')
        in_order_traversal(root.right)

if __name__ == "__main__":
    tree_root = None
    values = [random.randint(1, 50) for _ in range(10)]
    for val in values:
        tree_root = insert_into_tree(tree_root, val)
    in_order_traversal(tree_root)

