            raise ValueError("Name can only contain alphabetic characters")
        return v

    @validator('age')
    def age_must_be_valid(cls, v):
        if v < 18:
            raise ValueError("Age must be at least 18")
        return v

    @validator('hobbies')
    def hobbies_must_be_valid(cls, v):
        valid_hobbies = ["reading", "gaming", "traveling", "cooking", "painting", "photography", "hiking", "swimming", "coding", "music"]
        invalid_hobbies = [hobby for hobby in v if hobby not in valid_hobbies]
        if invalid_hobbies:
            raise ValueError(f"Invalid hobbies: {', '.join(invalid_hobbies)}")
        return v

