from abc import ABC, abstractmethod

class Creator:
    @abstractmethod
    def factory_method(self):
        pass

    def operation(self) -> str:
        product = self.factory_method()
        return f"Creator: The same creator's method returns [{product.operation()}]."

class Product(ABC):
    @abstractmethod
    def operation(self) -> str:
        pass

class ConcreteProductA(Product):
    def operation(self) -> str:
        return "{ConcreteProductA}"

class ConcreteProductB(Product):
    def operation(self) -> str:
        return "{ConcreteProductB}"

class ConcreteCreator(Creator):
    def factory_method(self) -> Product:
        return ConcreteProductA()

class AnotherConcreteCreator(Creator):
    def factory_method(self) -> Product:
        return ConcreteProductB()

def client_code(creator: Creator) -> None:
    print(f"Client: I'm not aware of the creator's class, but the result is full of {creator.operation()}")

if __name__ == "__main__":
    print("App: Launched with the first set of the creator.")
    client_code(ConcreteCreator())

    print("\n")

    print("App: Launched with the second set of the creator.")
    client_code(AnotherConcreteCreator())

