    if not midi.connected:
        return 'No MIDI device connected'
    try:
        success = midi.play_scale_sequence(channel, scale_name, root_note, sequence, velocity, duration, interval, octave)
        if success:
            sequence_display = []
            for note in sequence:
                if note == 0:
                    sequence_display.append('rest')
                else:
                    sequence_display.append(str(note))
            sequence_str = ', '.join(sequence_display)
            return f'Successfully played scale sequence using {scale_name} scale in {root_note} (channel {channel}, octave {octave}):\nSequence: {sequence_str}'
