class ObserverPatternExample:
    def __init__(self):
        self.subscribers = []

    def register(self, subscriber):
        if subscriber not in self.subscribers:
            self.subscribers.append(subscriber)
            return True
        return False

    def unregister(self, subscriber):
        if subscriber in self.subscribers:
            self.subscribers.remove(subscriber)
            return True
        return False

    def notify(self, message):
        for subscriber in self.subscribers:
            subscriber.update(message)

class Subscriber:
    def update(self, message):
        print(f"Received message: {message}")

if __name__ == "__main__":
    observer = ObserverPatternExample()
    subscriber1 = Subscriber()
    subscriber2 = Subscriber()

    observer.register(subscriber1)
    observer.register(subscriber2)

    observer.notify("New data available")
    observer.unregister(subscriber1)
    observer.notify("Another update")

