def parse_log_entries(log_lines):
    pattern = r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) - (INFO|ERROR): (.*)'
    parsed_data = []

    for line in log_lines:
        match = re.match(pattern, line)
        if match:
            timestamp, level, message = match.groups()
            parsed_data.append({
                'timestamp': timestamp,
                'level': level,
                'message': message
            })

    return parsed_data

