class ObserverPatternExample:
    class Subject:
        def __init__(self):
            self._observers = []
            self._temperature = 0

        def attach(self, observer):
            self._observers.append(observer)

        def detach(self, observer):
            self._observers.remove(observer)

        def notify(self):
            for observer in self._observers:
                observer.update(self._temperature)

        def set_temperature(self, temperature):
            self._temperature = temperature
            self.notify()

    class ConcreteObserver:
        def update(self, temperature):
            print(f"Current temperature is {temperature} degrees.")

    def main():
        subject = ObserverPatternExample.Subject()
        observer1 = ObserverPatternExample.ConcreteObserver()
        observer2 = ObserverPatternExample.ConcreteObserver()
        subject.attach(observer1)
        subject.attach(observer2)

        subject.set_temperature(22)
        subject.detach(observer1)
        subject.set_temperature(25)

    if __name__ == "__main__":
        main()

