import random

def generate_board(size):
    return [[random.choice(['X', 'O', None]) for _ in range(size)] for _ in range(size)]

def print_board(board):
    for row in board:
        print(" | ".join(str(cell) if cell else " " for cell in row))
        print("-" * (4 * len(row) - 1))

def check_winner(board, player):
    size = len(board)
    # Check rows and columns
    for i in range(size):
        if all(board[i][j] == player for j in range(size)) or all(board[j][i] == player for j in range(size)):
            return True
    # Check diagonals
    if all(board[i][i] == player for i in range(size)) or all(board[i][size - 1 - i] == player for i in range(size)):
        return True
    return False

def tic_tac_toe():
    board_size = 3
    board = generate_board(board_size)
    current_player = 'X'

    while True:
        print_board(board)
        try:
            row = int(input(f"Player {current_player}, enter row (0-{board_size-1}): "))
            col = int(input(f"Player {current_player}, enter column (0-{board_size-1}): "))
        except ValueError:
            print("Invalid input! Please enter numbers.")
            continue

        if row < 0 or row >= board_size or col < 0 or col >= board_size or not board[row][col] is None:
            print("Invalid move! Try again.")
            continue

        board[row][col] = current_player

        if check_winner(board, current_player):
            print_board(board)
            print(f"Player {current_player} wins!")
            break

        current_player = 'O

