class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, item_name, quantity, price):
        self.items.append({"item_name": item_name, "quantity": quantity, "price": price})

    def remove_item(self, item_name):
        self.items = [item for item in self.items if item["item_name"] != item_name]

    def calculate_total(self):
        total = sum(item["quantity"] * item["price"] for item in self.items)
        return total

    def display_cart(self):
        for item in self.items:
            print(f"{item['item_name']}: {item['quantity']} x ${item['price']}")

