class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_into_bst(root, value):
    if root is None:
        return TreeNode(value)
    if value < root.value:
        root.left = insert_into_bst(root.left, value)
    else:
        root.right = insert_into_bst(root.right, value)
    return root

def inorder_traversal(root):
    result = []
    if root:
        result = inorder_traversal(root.left)
        result.append(root.value)
        result += inorder_traversal(root.right)
    return result

if __name__ == "__main__":
    tree_root = None
    values = [8, 3, 10, 1, 6, 14, 4, 7, 13]
    for value in values:
        tree_root = insert_into_bst(tree_root, value)

    print(inorder_traversal(tree_root))

class FactoryPatternExample:
    class Creator:
        def __init__(self):
            self.products = {}

        def create_product(self, product_type):
            if product_type not in self.products:
                if product_type == "A":
                    self.products[product_type] = ProductA()
                elif product_type == "B":
                    self.products[product_type] = ProductB()
                else:
                    raise ValueError("Unknown product type")
            return self.products[product_type]

    class Product:
        def use(self):
            pass

    class ProductA(Product):
        def use(self):
            print("Using Product A")

    class ProductB(Product):
        def use(self):
            print("Using Product B")


def main():
    factory = FactoryPatternExample.Creator()
    product_a = factory.create_product("A")
    product_b = factory.create_product("B")

    product_a.use()
    product_b.use()


if __name__ == "__main__":
