import os

def load_image_files(image_dir):
    image_files = []
    supported_extensions = ['.jpg', '.jpeg', '.png', '.bmp']
    for root, dirs, files in os.walk(image_dir):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in supported_extensions:
                image_files.append(os.path.join(root, file))
    return image_files

def resize_image(image_path, width, height):
    from PIL import Image
    img = Image.open(image_path)
    resized_img = img.resize((width, height), Image.ANTIALIAS)
    resized_img.save(image_path)

def process_images(image_dir, output_dir, width, height):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    images = load_image_files(image_dir)
    for image_path in images:
        base_name = os.path.basename(image_path)
        output_path = os.path.join(output_dir, base_name)
        resize_image(image_path, width, height)
        print(f"Resized {image_path} to {output_path}")

if __name__ == "__main__":
    input_dir = "input_images"
    output_dir = "resized_images"
    new_width = 800
    new_height = 600
    process_images(input_dir, output_dir, new_width, new_height)

import csv

def read_csv_file(file_path):
    data = []
    with open(file_path, mode='r', newline='') as file:
        csv_reader = csv.DictReader(file)
        for row in csv_reader:
            data.append(row)
    return data

def write_csv_file(file_path, data):
    fieldnames = ['id', 'name', 'age']
    with open(file_path, mode='w', newline='') as file:
        writer = csv.DictWriter(file, fieldnames=fieldnames)
        writer.writeheader()
        for item in data:
            writer.writerow(item)

def process_data(input_file, output_file):
    data = read_csv_file(input_file)
    processed_data = []
    for row in data:
        if int(row['age']) > 30:
            row['status'] = 'Eligible'
        else:
            row['status'] = 'Not Eligible'
        processed_data.append(row)
    write_csv_file(output_file, processed_data)

if __name__ == "__main__":
    input_file = 'input.csv'
    output_file = 'output.csv'
    process_data(input_file, output_file)

