        is_dir_synced = group.get('dirSyncEnabled', False)
        if is_security:
            analysis['groupsByType']['security'] += 1
        if has_mail:
            analysis['groupsByType']['mail'] += 1
        if is_dynamic:
            analysis['groupsByType']['dynamic'] += 1
        else:
            analysis['groupsByType']['assigned'] += 1
        if is_dir_synced:
            analysis['groupsByType']['dirSync'] += 1
        if group.get('isAssignableToRole', False):
            analysis['assignableToRole'] += 1
    return analysis

def binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def merge_sort(arr):
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left_half = merge_sort(arr[:mid])
    right_half = merge_sort(arr[mid:])

    return merge(left_half, right_half)

def merge(left, right):
    result = []
    i, j = 0, 0

    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1

    result.extend(left[i:])
    result.extend(right[j:])

    return result

