import argparse

def parse_arguments():
    parser = argparse.ArgumentParser(description="CLI tool for file operations")
    parser.add_argument("file_path", type=str, help="Path to the file")
    parser.add_argument("--mode", choices=["read", "write"], default="read", help="Operation mode (default: read)")
    parser.add_argument("--append", action="store_true", help="Append to the file if in write mode")
    return parser.parse_args()

def read_file(file_path, append=False):
    try:
        with open(file_path, "r") as file:
            content = file.read()
            print("File content:")
            print(content)
    except FileNotFoundError:
        print(f"File not found: {file_path}")

def write_file(file_path, append=False):
    content = input("Enter content to write: ")
    try:
        with open(file_path, "a" if append else "w") as file:
            file.write(content + "\n")
            print("Content written successfully.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    args = parse_arguments()
    if args.mode == "read":
        read_file(args.file_path)
    elif args.mode == "write":
        write_file(args.file_path, args.append)

