class GraphNode:
    def __init__(self, value):
        self.value = value
        self.neighbors = []

def add_edge(node1, node2):
    node1.neighbors.append(node2)
    node2.neighbors.append(node1)

def find_path(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return path
    for node in graph:
        if node not in path:
            newpath = find_path(graph, node, end, path)
            if newpath:
                return newpath
    return None

def breadth_first_search(graph, start):
    visited, queue = set(), [start]
    while queue:
        vertex = queue.pop(0)
        if vertex not in visited:
            visited.add(vertex)
            queue.extend([neighbor for neighbor in vertex.neighbors if neighbor not in visited])
    return list(visited)

