class TreeNode:
    def __init__(self, value):
        self.value = value
        self.children = []

def add_child(parent, child):
    parent.children.append(child)

def print_tree(root, level=0):
    indent = "  " * level
    print(f"{indent}{root.value}")
    for child in root.children:
        print_tree(child, level + 1)

def find_node(root, target_value):
    if root.value == target_value:
        return root
    for child in root.children:
        found_node = find_node(child, target_value)
        if found_node:
            return found_node
    return None

def main():
    root = TreeNode("A")
    b = TreeNode("B")
    c = TreeNode("C")
    d = TreeNode("D")
    e = TreeNode("E")

    add_child(root, b)
    add_child(root, c)
    add_child(b, d)
    add_child(c, e)

    print("Tree structure:")
    print_tree(root)

    target = input("Enter the value of the node you want to find: ")
    node = find_node(root, target)
    if node:
        print(f"Found node with value {node.value}")
    else:
        print("Node not found")

if __name__ == "__main__":
    main()

class Graph:
    def __init__(self):
        self.adjacency_list = {}

    def add_vertex(self, vertex):
        if vertex not in self.adjacency_list:
            self.adjacency_list[vertex] = []

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.adjacency_list and vertex2 in self.adjacency_list:
            self.adjacency_list[vertex1].append(vertex2)
            self.adjacency_list[vertex2].append(vertex1)

    def bfs(self, start_vertex):
        visited = set()
        queue = [start_vertex]
        visited.add(start_vertex)
        while queue:
            current_vertex = queue.pop(0)
            print(current_vertex, end=" ")
            for neighbor in self.adjacency_list[current_vertex]:
                if neighbor not in visited:
                    queue.append(neighbor)
                    visited.add(neighbor)

    def dfs(self, start_vertex):
        visited = set()
        stack = [start_vertex]

        while stack:
            current_vertex = stack.pop()
            if current_vertex not in visited:
                print(current_vertex, end=" ")
                visited.add(current_vertex)
                for neighbor in reversed(self.adjacency_list[current_vertex]):
                    if neighbor not in visited:
                        stack.append(neighbor)

# Example usage
