import argparse

def parse_config_file(config_file):
    config_data = {}
    with open(config_file, 'r') as file:
        lines = file.readlines()
        for line in lines:
            key, value = line.strip().split('=')
            config_data[key] = value
    return config_data

def main():
    parser = argparse.ArgumentParser(description="CLI tool for parsing configuration files")
    parser.add_argument("config_file", help="Path to the configuration file")
    parser.add_argument("--section", help="Specific section to parse")

    args = parser.parse_args()

    config_data = parse_config_file(args.config_file)

    if args.section:
        if args.section in config_data:
            print(f"Section '{args.section}': {config_data[args.section]}")
        else:
            print(f"Section '{args.section}' not found in the configuration file.")
    else:
        print(config_data)

if __name__ == "__main__":
    main()

import os

def resize_image(input_path, output_path, width, height):
    if not os.path.exists(input_path):
        return "Input image does not exist."

    if width <= 0 or height <= 0:
        return "Width and height must be positive integers."

    try:
        from PIL import Image
        img = Image.open(input_path)
        resized_img = img.resize((width, height))
        resized_img.save(output_path)
        return "Image resized successfully."
    except Exception as e:
        return str(e)

def crop_image(input_path, output_path, x, y, width, height):
    if not os.path.exists(input_path):
        return "Input image does not exist."

    if x < 0 or y < 0 or width <= 0 or height <= 0:
        return "X, Y, width, and height must be non-negative integers."

    try:
        from PIL import Image
        img = Image.open(input_path)
        cropped_img = img.crop((x, y, x + width, y + height))
        cropped_img.save(output_path)
        return "Image cropped successfully."
    except Exception as e:
        return str(e)

