import argparse

def parse_args():
    parser = argparse.ArgumentParser(description='Process command-line arguments for a simple file reader.')

    parser.add_argument('--file', required=True, help='Path to the input file')
    parser.add_argument('--encoding', default='utf-8', help='File encoding')
    parser.add_argument('--lines', type=int, help='Number of lines to read')

    args = parser.parse_args()
    return args

def read_file(args):
    try:
        with open(args.file, 'r', encoding=args.encoding) as f:
            if args.lines:
                for _ in range(args.lines):
                    print(f.readline(), end='')
            else:
                print(f.read())
    except FileNotFoundError:
        print(f"Error: File '{args.file}' not found.")
    except IOError:
        print(f"Error: Could not read file '{args.file}'.")

if __name__ == "__main__":
    args = parse_args()
    read_file(args)

