def calculate_distance(lat1: float, lon1: float, lat2: float, lon2: float, unit: str='km') -> Dict[str, Any]:
    try:
        from geopy.distance import geodesic
        point1 = (lat1, lon1)
        point2 = (lat2, lon2)
        distance = geodesic(point1, point2)
        if unit.lower() == 'miles':
            result_distance = distance.miles
        elif unit.lower() == 'nm':
            result_distance = distance.nautical
        else:
            result_distance = distance.kilometers
        return {'success': True, 'distance': round(result_distance, 2), 'unit': unit, 'point1': {'latitude': lat1, 'longitude': lon1}, 'point2': {'latitude': lat2, 'longitude': lon2}, 'calculation_method': 'geodesic'}
    except Exception as e:
        return {'success': False, 'error': f'Distance calculation error: {str(e)}'}

