def check_win(board, player):
    size = len(board)
    for i in range(size):
        if all([board[i][j] == player for j in range(size)]) or all([board[j][i] == player for j in range(size)]):
            return True
        if i == size - 1 and board[i][i] == player and board[i][size - 1 - i] == player:
            return True
    return False

