class BinaryTreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert_node(root, value):
    if root is None:
        return BinaryTreeNode(value)
    else:
        if value < root.value:
            root.left = insert_node(root.left, value)
        else:
            root.right = insert_node(root.right, value)
    return root

def inorder_traversal(root):
    result = []
    if root:
        result += inorder_traversal(root.left)
        result.append(root.value)
        result += inorder_traversal(root.right)
    return result

def find_largest_smaller_value(root, target):
    stack = []
    current = root
    closest = float('-inf')

    while current or stack:
        while current:
            stack.append(current)
            current = current.left

        current = stack.pop()

        if current.value < target:
            closest = max(closest, current.value)

        if closest == target - 1:
            break

        current = current.right

    return closest if closest != float('-inf') else None

# Example usage
root = None
data = [8, 3, 10, 1, 6, 14, 4, 7, 13]
for value in data:
    root = insert_node(root, value)

print(inorder_traversal(root))  # Expected: [1, 3, 4, 6, 7, 8, 10, 13, 14]
print(find_largest_smaller_value(root, 11))  # Expected: 10
print(find_largest_smaller_value(root, 2))   # Expected: 1

class Graph:
    def __init__(self):
        self.vertices = {}

    def add_vertex(self, vertex_id):
        if vertex_id not in self.vertices:
            self.vertices[vertex_id] = []

    def add_edge(self, v1, v2):
        if v1 in self.vertices and v2 in self.vertices:
            self.vertices[v1].append(v2)
            self.vertices[v2].append(v1)

    def dfs_traverse(self, start_vertex):
        visited = set()
        stack = [start_vertex]
        traversal_order = []

        while stack:
            current_vertex = stack.pop()
            if current_vertex not in visited:
                visited.add(current_vertex)
                traversal_order.append(current_vertex)
                for neighbor in self.vertices[current_vertex]:
                    if neighbor not in visited:
                        stack.append(neighbor)

        return traversal_order

    def bfs_traverse(self, start_vertex):
        visited = set()
        queue = [start_vertex]
        traversal_order = []

        while queue:
            current_vertex = queue.pop(0)
            if current_vertex not in visited:
                visited.add(current_vertex)
                traversal_order.append(current_vertex)
                for neighbor in self.vertices[current_vertex]:
                    if neighbor not in visited:
                        queue.append(neighbor)

        return traversal_order

graph = Graph()
graph.add_vertex(1)
graph.add_vertex(2)
graph.add_vertex(3)
graph.add_vertex(4)
graph.add_vertex(5)
graph.add_vertex(6)
graph.add_edge(1, 2)
graph.add_edge(1, 3)
graph.add_edge(2, 4)
graph.add_edge(2, 5)
graph.add_edge(3, 6)

print("DFS Traversal:", graph.dfs_traverse(1))
print("BFS Traversal:", graph.bfs_traverse(1))

from abc import ABC, abstractmethod

class Observer(ABC):
    @abstractmethod
    def update(self, message: str):
        pass

class ConcreteObserver(Observer):
    def __init__(self, name):
        self.name = name

    def update(self, message: str):
        print(f"{self.name} received message: {message}")

class Subject:
    def __init__(self):
        self._observers = []
        self._message = ""

    def attach(self, observer: Observer):
        self._observers.append(observer)

    def detach(self, observer: Observer):
        self._observers.remove(observer)

    def notify(self, message: str):
        self._message = message
        for observer in self._observers:
            observer.update(message)

if __name__ == "__main__":
    subject = Subject()

    observer1 = ConcreteObserver("Observer 1")
    observer2 = ConcreteObserver("Observer 2")

    subject.attach(observer1)
    subject.attach(observer2)

    subject.notify("Hello observers!")
    subject.detach(observer1)
    subject.notify("Observer 1 is gone.")

import random

class NumberGuessingGame:
    def __init__(self):
        self.secret_number = random.randint(1, 100)
        self.attempts = 0

    def play(self):
        print("Welcome to the Number Guessing Game!")
        while True:
            try:
                guess = int(input("Guess a number between 1 and 100: "))
                self.attempts += 1
                if guess < self.secret_number:
                    print("Too low!")
                elif guess > self.secret_number:
                    print("Too high!")
                else:
                    print(f"Congratulations! You guessed the number in {self.attempts} attempts.")
                    break
            except ValueError:
                print("Please enter a valid number.")

if __name__ == "__main__":
    game = NumberGuessingGame()
    game.play()

