def parse_document(content: str, document_name: str, default_parties: List[str]=[]) -> Dict:
    date_patterns = ['(?:on|dated|as of)\\s+(\\d{1,2}/\\d{1,2}/\\d{4})', '(?:on|dated|as of)\\s+([A-Za-z]+\\s+\\d{1,2},?\\s+\\d{4})', '(\\d{1,2}/\\d{1,2}/\\d{4})', '([A-Za-z]+\\s+\\d{1,2},?\\s+\\d{4})']
    events_found = []
    lines = content.split('\n')
    for i, line in enumerate(lines):
        line = line.strip()
        if not line:
            continue
        for pattern in date_patterns:
            matches = re.finditer(pattern, line, re.I)
            for match in matches:
                date_str = match.group(1)
                start = max(0, match.start() - 50)
                end = min(len(line), match.end() + 100)
                context = line[start:end].strip()
                if start > 0:
                    context = '...' + context
                if end < len(line):
                    context = context + '...'
                events_found.append({'date_string': date_str, 'context': context, 'line_number': i + 1, 'suggested_description': context[:100]})
    added_events = []
    for event_data in events_found:
        result = add_event(date_string=event_data['date_string'], description=event_data['suggested_description'], parties=default_parties, document_source=document_name, document_excerpt=event_data['context'], tags=['auto-extracted'])
        if result['status'] == 'success':
            added_events.append(result['event_id'])
    return {'status': 'success', 'events_found': len(events_found), 'events_added': len(added_events), 'event_ids': added_events, 'message': f'Extracted {len(added_events)} events from {document_name}'}

