from abc import ABC, abstractmethod

class Observer:
    def update(self, message):
        pass

class NotificationService(Observer):
    def __init__(self):
        self.messages = []

    def add_message(self, message):
        self.messages.append(message)

    def clear_messages(self):
        self.messages = []

class ConsoleNotification(Observer):
    def update(self, message):
        print(f"Console Notification: {message}")

class EmailNotification(Observer):
    def update(self, message):
        print(f"Email Notification: {message}")

class Subject(ABC):
    @abstractmethod
    def attach(self, observer):
        pass

    @abstractmethod
    def detach(self, observer):
        pass

    @abstractmethod
    def notify(self):
        pass

class SystemStatusSubject(Subject):
    def __init__(self):
        self._observers = []

    def attach(self, observer):
        self._observers.append(observer)

    def detach(self, observer):
        self._observers.remove(observer)

    def notify(self):
        for observer in self._observers:
            observer.update("System status updated")

def main():
    subject = SystemStatusSubject()
    console_observer = ConsoleNotification()
    email_observer = EmailNotification()

    subject.attach(console_observer)
    subject.attach(email_observer)

    subject.notify()

    subject.detach(console_observer)
    subject.notify()

if __name__ == "__main__":
    main()

